changeSet.sql:
ALTER TABLE team_repositories ADD COLUMN automatic_workflow_analysis BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE ai_workflow_analyses ADD COLUMN automatically_queued BOOLEAN NOT NULL DEFAULT FALSE;
UPDATE ai_workflow_analyses a SET automatically_queued = TRUE
  FROM agent_sessions s WHERE s.id = a.agent_session_id
   AND s.team_repository_id = a.team_repository_id AND s.trigger_kind = 'analysis'
   AND s.created_by = 'logos-agent (analysis)' AND s.status = 'queued';
